val dbproperties = providers.gradlePropertiesPrefixedBy("dburl").orNull

tasks.named<ProcessResources>("processResources") {
    exclude("META-INF/persistence.xml")
    filesMatching("config/persistence.properties") {
        expand(dbproperties ?: mapOf<String, String>())
    }
}


tasks.named<Jar>("jar") {
    duplicatesStrategy = DuplicatesStrategy.INCLUDE
}

tasks.register<Copy>("copyPersistenceXml") {
    from("src/main/resources/META-INF/persistence.xml")
    into("${layout.buildDirectory.get()}/classes/kotlin/main/META-INF")
    mustRunAfter(tasks.named("compileKotlin"))
}

tasks.named("classes") {
    dependsOn("copyPersistenceXml")
}


val dburl = project.property("dburl").toString()

flyway {
    url = dburl
    user = "sa"
}

